#include <vector>
#define main original_pathtracer_main
#include "../.local/raytracing-cuda/main.cu"
#undef main
int main(int argc,char**argv){int nx=argc>1?atoi(argv[1]):1200,ny=argc>2?atoi(argv[2]):800,ns=argc>3?atoi(argv[3]):10;vec3*fb;curandState*states,*worldState;hitable**list,**world;camera**cam;
checkCudaErrors(cudaMalloc(&fb,nx*ny*sizeof(vec3)));checkCudaErrors(cudaMalloc(&states,nx*ny*sizeof(curandState)));checkCudaErrors(cudaMalloc(&worldState,sizeof(curandState)));checkCudaErrors(cudaMalloc(&list,488*sizeof(hitable*)));checkCudaErrors(cudaMalloc(&world,sizeof(hitable*)));checkCudaErrors(cudaMalloc(&cam,sizeof(camera*)));
rand_init<<<1,1>>>(worldState);checkCudaErrors(cudaDeviceSynchronize());create_world<<<1,1>>>(list,world,cam,nx,ny,worldState);checkCudaErrors(cudaDeviceSynchronize());dim3 block(8,8),grid((nx+7)/8,(ny+7)/8);cudaEvent_t start,stop;checkCudaErrors(cudaEventCreate(&start));checkCudaErrors(cudaEventCreate(&stop));checkCudaErrors(cudaEventRecord(start));render_init<<<grid,block>>>(nx,ny,states);render<<<grid,block>>>(fb,nx,ny,ns,cam,world,states);checkCudaErrors(cudaEventRecord(stop));checkCudaErrors(cudaEventSynchronize(stop));float ms;checkCudaErrors(cudaEventElapsedTime(&ms,start,stop));std::vector<float>pixels(nx*ny*3);checkCudaErrors(cudaMemcpy(pixels.data(),fb,pixels.size()*4,cudaMemcpyDeviceToHost));FILE*f=fopen("reports/pathtracer-full-native.bin","wb");if(!f)return 2;fwrite(pixels.data(),4,pixels.size(),f);fclose(f);free_world<<<1,1>>>(list,world,cam);checkCudaErrors(cudaDeviceSynchronize());checkCudaErrors(cudaFree(list));checkCudaErrors(cudaFree(world));checkCudaErrors(cudaFree(cam));checkCudaErrors(cudaFree(states));checkCudaErrors(cudaFree(worldState));checkCudaErrors(cudaFree(fb));checkCudaErrors(cudaEventDestroy(start));checkCudaErrors(cudaEventDestroy(stop));printf("{\"width\":%d,\"height\":%d,\"samples\":%d,\"gpuMs\":%.6f}\n",nx,ny,ns,ms);}
